// batch78: reducer + experimental/utils + utils — data-driven from
// batch78_truth.json (truth generated by Node vm against the real TS sources).
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/base.dart'
    show IObservable, IObservableWithChange, IReader, ITransaction;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/changeTracker.dart'
    show ChangeSummary, IChangeContext, IChangeTracker, RecordedChange;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/experimental/reducer.dart'
    as rr;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/experimental/utils.dart'
    as eu;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/observables/derived.dart'
    as d;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/observables/observableValue.dart'
    as ov;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/reactions/autorun.dart'
    as au;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/transaction.dart'
    as tx;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/utils/utils.dart'
    as u;

Map<String, dynamic> _truth() => jsonDecode(
      File('tool/ts2dart/batch78_truth.json').readAsStringSync(),
    ) as Map<String, dynamic>;

/// 1:1: the change tracker used in the truth script for the reducer.
class _TwoObsTracker implements IChangeTracker<ChangeSummary> {
  _TwoObsTracker(this.o1, this.o2);
  final IObservableWithChange<Object?, Object?> o1;
  final IObservableWithChange<Object?, Object?> o2;

  @override
  ChangeSummary createChangeSummary(ChangeSummary? previous) => ChangeSummary();

  @override
  bool handleChange(IChangeContext ctx, ChangeSummary change) {
    if (ctx.didChange(o1)) {
      change.changes.add(RecordedChange('o1', ctx.change));
    }
    if (ctx.didChange(o2)) {
      change.changes.add(RecordedChange('o2', ctx.change));
    }
    return true;
  }

  @override
  void beforeUpdate(IReader reader, ChangeSummary change) {
    change['o1'] = o1.read(reader);
    change['o2'] = o2.read(reader);
  }
}

String _summaryJson(ChangeSummary s) {
  final buf = StringBuffer('{"changes":[');
  for (int i = 0; i < s.changes.length; i++) {
    if (i > 0) buf.write(',');
    final c = s.changes[i];
    buf.write('{"key":"${c.key}","change":${c.change}}');
  }
  buf.write('],"o1":${s['o1']},"o2":${s['o2']}}');
  return buf.toString();
}

/// Tracker for the settable reducer: records raw changes into a List<int>.
class _RawTracker implements IChangeTracker<List<Object?>> {
  _RawTracker(this.o1);
  final IObservableWithChange<Object?, Object?> o1;

  @override
  List<Object?> createChangeSummary(List<Object?>? previous) => <Object?>[];

  @override
  bool handleChange(IChangeContext ctx, List<Object?> change) {
    if (ctx.didChange(o1)) change.add(ctx.change);
    return true;
  }

  @override
  void beforeUpdate(IReader reader, List<Object?> change) {
    o1.read(reader);
  }
}

void main() {
  group('batch78 reducer', () {
    test('initial/update/disposeFinal with changeTracker', () {
      final t = _truth()['reducer'] as Map<String, dynamic>;
      final log = <String>[];
      final o1 = ov.observableValue<int, Object?>('o1', 5);
      final o2 = ov.observableValue<int, Object?>('o2', 9);
      final sum = rr.observableReducer<int, ChangeSummary, int>(null,
          rr.IReducerOptions<int, ChangeSummary, int>(
        initial: () {
          log.add('createInitial');
          return o1.get() + o2.get();
        },
        disposeFinal: (v) => log.add('disposeFinal $v'),
        changeTracker: _TwoObsTracker(o1, o2),
        update: (reader, prev, changes) {
          log.add('update ${_summaryJson(changes)}');
          int delta = 0;
          for (final c in changes.changes) {
            delta += (c.change as int?) ?? 0;
          }
          reader.reportChange(delta);
          final result = prev + delta;
          log.add('update -> $result');
          return result;
        },
      ));

      expect(log, t['initialAfterCreate']);
      final beforeObserveGet = sum.get();
      expect(beforeObserveGet, t['beforeObserveGet']);
      expect(log, t['logAfterGet']);
      log.clear();

      final seen = <int>[];
      final disposable = au.autorun((reader) => seen.add(sum.read(reader)));
      final afterObserve = t['afterObserve'] as Map<String, dynamic>;
      expect(log, afterObserve['log']);
      expect(seen, afterObserve['seen']);
      log.clear();

      tx.transaction((txx) {
        o1.set(o1.get() + 1, txx, 1);
        o2.set(o2.get() + 3, txx, 3);
      });
      final afterTx = t['afterTx'] as Map<String, dynamic>;
      expect(log, afterTx['log']);
      expect(seen, afterTx['seen']);
      log.clear();

      disposable.dispose();
      expect(log, (t['afterDispose'] as Map<String, dynamic>)['log']);
    });

    test('settable: set requires observer and updates prevValue', () {
      final t = _truth()['reducerSettable'] as Map<String, dynamic>;
      final o1 = ov.observableValue<int, Object?>('s1', 0);
      final r = rr.observableReducerSettable<int, List<Object?>, int>(null,
          rr.IReducerOptions<int, List<Object?>, int>(
        initial: 10,
        changeTracker: _RawTracker(o1),
        update: (reader, prev, changes) =>
            prev + changes.fold<int>(0, (a, b) => a + ((b as int?) ?? 0)),
      ));

      String? setBeforeObserveError;
      try {
        r.set(99, null, 0);
      } catch (e) {
        setBeforeObserveError = 'BugIndicatingError: ${e.toString()}';
      }
      expect(setBeforeObserveError, t['setBeforeObserveError']);

      final seen = <int>[];
      final dd = au.autorun((reader) => seen.add(r.read(reader)));
      expect(seen, t['initialSeen']);
      r.set(50, null, 7);
      expect(seen, t['afterSetSeen']);
      expect(r.get(), t['valueAfterSet']);
      o1.set(3, null, 3);
      expect(seen, t['afterSourceSeen']);
      dd.dispose();
      expect(r.get(), t['finalGet']);
    });
  });

  group('batch78 experimental utils', () {
    test('latestChangedValue', () {
      final t = _truth()['latestChangedValue'] as Map<String, dynamic>;
      final a = ov.observableValue<int, Object?>('a', 1);
      final b = ov.observableValue<int, Object?>('b', 10);
      final latest = eu.latestChangedValue<int>(
          null, <IObservable<Object?>>[a, b]);
      expect(latest.get(), t['initial']);
      final seen = <int>[];
      final dd = au.autorun((reader) => seen.add(latest.read(reader)));
      expect(seen, t['afterObserve']);
      a.set(2, null, null);
      expect(seen, t['afterA']);
      b.set(20, null, null);
      expect(seen, t['afterB']);
      tx.transaction((txx) {
        a.set(3, txx, null);
        b.set(30, txx, null);
      });
      expect(seen, t['afterTx']);
      dd.dispose();
      expect(latest.get(), t['afterDisposeGet']);
    });

    test('derivedConstOnceDefined caches first defined value', () {
      final t = _truth()['derivedConstOnceDefined'] as Map<String, dynamic>;
      final src = ov.observableValue<int, Object?>('c', 1);
      int computations = 0;
      final c = eu.derivedConstOnceDefined<int>(null, (reader) {
        computations++;
        return reader.readObservable(src) * 2;
      });
      expect(c.get(), t['g1']);
      expect(computations, t['c1']);
      final dd = au.autorun((reader) => c.read(reader));
      expect(c.get(), t['g2']);
      expect(computations, t['c2']);
      src.set(5, null, null);
      expect(c.get(), t['g3']);
      expect(computations, t['c3']);
      dd.dispose();
      expect(c.get(), t['g4']);
      expect(computations, t['c4']);
    });
  });

  group('batch78 utils', () {
    test('keepObserved / recomputeInitiallyAndOnChange', () {
      final t = _truth()['utilsKeep'] as Map<String, dynamic>;
      final src = ov.observableValue<int, Object?>('k', 1);
      int recomputes = 0;
      final dd = d.derived<int, Object?>((reader) {
        recomputes++;
        return reader.readObservable(src) * 2;
      });
      final before = t['beforeKeep'] as Map<String, dynamic>;
      expect(dd.get(), before['g']);
      expect(recomputes, before['recomputes']);

      final keep = u.keepObserved(dd);
      final k1 = t['afterKeep1'] as Map<String, dynamic>;
      expect(dd.get(), k1['g']);
      expect(recomputes, k1['recomputes']);
      final k2 = t['afterKeep2'] as Map<String, dynamic>;
      expect(dd.get(), k2['g']);
      expect(recomputes, k2['recomputes']);

      src.set(2, null, null);
      expect(recomputes, t['afterSetNoRead']);
      final sr = t['afterSetRead'] as Map<String, dynamic>;
      expect(dd.get(), sr['g']);
      expect(recomputes, sr['recomputes']);

      keep.dispose();
      final ad = t['afterDispose'] as Map<String, dynamic>;
      expect(dd.get(), ad['g']);
      expect(recomputes, ad['recomputes']);

      final src2 = ov.observableValue<int, Object?>('r', 7);
      final dd2 = d.derived<int, Object?>((reader) => reader.readObservable(src2) + 1);
      final values = <int>[];
      final rec = u.recomputeInitiallyAndOnChange(dd2, (v) => values.add(v));
      expect(values, t['initialRecompute']);
      src2.set(8, null, null);
      expect(values, t['afterSourceChange']);
      rec.dispose();
    });

    test('derivedObservableWithCache', () {
      final t = _truth()['derivedObservableWithCache'] as Map<String, dynamic>;
      final src = ov.observableValue<int, Object?>('w', 3);
      final calls = <Object?>[];
      final w = u.derivedObservableWithCache<int>(null, (reader, last) {
        calls.add(last);
        return (last ?? 0) + reader.readObservable(src);
      });
      expect(w.get(), t['g1']);
      final dd = au.autorun((reader) => w.read(reader));
      expect(w.get(), t['g2']);
      src.set(4, null, null);
      expect(w.get(), t['g3']);
      dd.dispose();
      expect(calls, t['calls']);
    });

    test('isObservable', () {
      final t = _truth()['isObservable'] as Map<String, dynamic>;
      final ovv = ov.observableValue<int, Object?>('io', 1);
      expect(u.isObservable(ovv), t['observable']);
      expect(u.isObservable(<String, Object?>{}), t['plainObject']);
      expect(u.isObservable(null), t['nullValue']);
      expect(
          u.isObservable(_ReaderLike()),
          t['readerLike']);
      expect(u.isObservable(_ReadOnlyLike()), t['readOnly']);
    });
  });
}

class _ReaderLike {
  Object? read(IReader? reader) => null;
  void reportChanges() {}
}

class _ReadOnlyLike {
  Object? read(IReader? reader) => null;
}
